// SPDX-License-Identifier: MIT
//! The official RFC 9381 Appendix B.3 test vectors for
//! ECVRF-EDWARDS25519-SHA512-TAI (Examples 16, 17, 18 in the RFC's own
//! numbering — the secret keys/messages themselves are drawn from RFC
//! 8032 §7.1's Ed25519 vectors, but every ECVRF-specific field (`x`, `H`,
//! `k_string`, `k`, `U`, `V`, `pi`, `beta`) is unique to RFC 9381 and was
//! generated by the reference implementation the RFC itself cites,
//! <https://github.com/reyzin/ecvrf> — see Appendix B's own preamble).
//!
//! Fetched directly from `https://www.rfc-editor.org/rfc/rfc9381.txt`
//! (the IETF's own canonical RFC repository) and extracted with a
//! regex-based structured-extraction pass (joining each field's
//! line-wrapped hex digits, stripping the `k*B =`/`k*H =` inline
//! annotations on the `U`/`V` lines) rather than hand-transcribed, to
//! avoid manual hex-transcription error on 80-plus-byte fields; every
//! field's byte length was then cross-checked against RFC 9381 §5.5's
//! own stated widths (`SK`/`PK`/`x`/`H`/`k` = 32 bytes, `k_string` = 64
//! bytes, `U`/`V` = 32 bytes, `pi` = `ptLen+cLen+qLen` = 80 bytes,
//! `beta` = `hLen` = 64 bytes) before being trusted — see `../NOTICE`.

pub const Vector = struct {
    /// RFC 9381's own example number (16, 17, 18) — kept for cross-
    /// referencing back to the RFC text in test failure messages.
    example: u8,
    /// 64 hex chars (32-byte secret key seed).
    sk: []const u8,
    /// 64 hex chars (32-byte compressed public key `Y`).
    pk: []const u8,
    /// Variable-length hex VRF input `alpha_string` (0, 2, or 4 hex chars
    /// in this set — the empty string, 1 byte, and 2 bytes respectively).
    alpha: []const u8,
    /// 64 hex chars (32-byte clamped VRF secret scalar `x`).
    x: []const u8,
    /// The `try_and_increment` counter that produced `H` (0, 1, or 0).
    ctr: u8,
    /// 64 hex chars (32-byte compressed `H = encode_to_curve(...)`).
    h: []const u8,
    /// 128 hex chars (64-byte SHA-512 output BEFORE reduction mod q —
    /// RFC 9381 §5.4.2.2's `k_string`).
    k_string: []const u8,
    /// 64 hex chars (32-byte nonce `k = k_string mod q`).
    k: []const u8,
    /// 64 hex chars (32-byte compressed `U = k*B`).
    u: []const u8,
    /// 64 hex chars (32-byte compressed `V = k*H`).
    v: []const u8,
    /// 160 hex chars (80-byte proof `pi_string = Gamma || c || s`).
    pi: []const u8,
    /// 128 hex chars (64-byte VRF output `beta_string`).
    beta: []const u8,
};

pub const vectors = [_]Vector{
    // RFC 9381 Appendix B.3, Example 16 (alpha = the empty string; SK/PK
    // from RFC 8032 §7.1's first Ed25519 test vector).
    .{
        .example = 16,
        .sk = "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
        .pk = "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a",
