    // Example 18 (alpha = 2 bytes, 0xaf82).
    .{
        .example = 18,
        .sk = "c5aa8df43f9f837bedb7442f31dcb7b166d38535076f094b85ce3a2e0b4458f7",
        .pk = "fc51cd8e6218a1a38da47ed00230f0580816ed13ba3303ac5deb911548908025",
