    },
};

test "vector count matches RFC 9381 Appendix B.3 (Examples 16, 17, 18)" {
    const std = @import("std");
    try std.testing.expectEqual(@as(usize, 3), vectors.len);
}

test "hex field lengths match RFC 9381 §5.5's stated widths" {
    const std = @import("std");
    for (vectors) |vec| {
        try std.testing.expectEqual(@as(usize, 64), vec.sk.len);
        try std.testing.expectEqual(@as(usize, 64), vec.pk.len);
        try std.testing.expectEqual(@as(usize, 0), vec.alpha.len % 2);
        try std.testing.expectEqual(@as(usize, 64), vec.x.len);
        try std.testing.expectEqual(@as(usize, 64), vec.h.len);
        try std.testing.expectEqual(@as(usize, 128), vec.k_string.len);
        try std.testing.expectEqual(@as(usize, 64), vec.k.len);
        try std.testing.expectEqual(@as(usize, 64), vec.u.len);
        try std.testing.expectEqual(@as(usize, 64), vec.v.len);
        try std.testing.expectEqual(@as(usize, 160), vec.pi.len);
        try std.testing.expectEqual(@as(usize, 128), vec.beta.len);
    }
}
